/**
 * Builds no-ZIP deliverables so the code can always be retrieved, even when a
 * browser/host blocks ZIP downloads:
 *
 *   public/ankit-traders-source-code.txt        — every project file, plain text
 *   public/ankit-traders-source-bundle.html     — self-extracting viewer:
 *                                                 open it, copy or download each file
 *   src/generated/source-manifest.json          — same files, used by /api/source
 */
import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const top = "ankit-traders-billing";

const SPECIFIC = [
  "package.json",
  "package-lock.json",
  "tsconfig.json",
  "next.config.ts",
  "next-env.d.ts",
  "postcss.config.mjs",
  "eslint.config.mjs",
  "drizzle.config.json",
  "vercel.json",
  "README.md",
  "DEPLOY.md",
  "GITHUB-PUSH.md",
  ".env.example",
  ".gitignore",
  "push-to-github.sh",
  "push-to-github.ps1",
  "standalone/index.template.html",
  "standalone/app.js",
  "scripts/build-standalone.mjs",
  "scripts/build-project-zip.mjs",
  "scripts/build-source-bundle.mjs",
  "public/manifest.json",
];

const DIRS = [
  { dir: "src", exts: [".ts", ".tsx", ".css", ".json"] },
  { dir: "standalone", exts: [".html", ".js", ".css"] },
  { dir: "scripts", exts: [".mjs"] },
];

const TEXT_EXT = new Set([".ts", ".tsx", ".js", ".mjs", ".json", ".css", ".html", ".md", ".txt", ".sh", ".ps1", ".example", ".gitignore"]);

const skip = (rel) => {
  if (rel.startsWith("node_modules") || rel.startsWith(".next") || rel.startsWith(".git")) return true;
  if (rel.startsWith("src/generated")) return true;
  if (rel.startsWith("public/standalone")) return true;
  if (rel.includes("seed-data")) return false;
  return false;
};

const files = new Map();

const addFile = (abs) => {
  const rel = path.relative(root, abs).split(path.sep).join("/");
  if (skip(rel)) return;
  const ext = path.extname(abs) || (rel.endsWith(".gitignore") ? ".gitignore" : "");
  if (!TEXT_EXT.has(ext) && !rel.endsWith(".env.example") && !rel.endsWith(".gitignore")) return;
  const content = fs.readFileSync(abs, "utf8");
  files.set(rel, content);
};

for (const rel of SPECIFIC) {
  const abs = path.join(root, rel);
  if (fs.existsSync(abs)) addFile(abs);
  else console.warn(`  (missing) ${rel}`);
}

const walk = (relDir, exts) => {
  const absDir = path.join(root, relDir);
  if (!fs.existsSync(absDir)) return;
  for (const entry of fs.readdirSync(absDir, { withFileTypes: true })) {
    const abs = path.join(absDir, entry.name);
    if (entry.isDirectory()) walk(path.join(relDir, entry.name), exts);
    else if (exts.includes(path.extname(entry.name))) addFile(abs);
  }
};
for (const { dir, exts } of DIRS) walk(dir, exts);

const entries = [...files.entries()].sort(([a], [b]) => a.localeCompare(b));
const payload = Object.fromEntries(entries);
const json = JSON.stringify(payload);

/* ------------------------------- plain text ------------------------------ */
const bar = "=".repeat(78);
const text = [
  "ANKIT TRADERS BILLING — COMPLETE SOURCE CODE (no ZIP needed)",
  `Generated ${new Date().toISOString()}`,
  "",
  "How to use:",
  "  1. Create a GitHub repository, then use 'Add file → Create new file'.",
  "  2. For each block below copy the text between the BEGIN/END lines and save it",
  "     at the path shown in the BEGIN line.",
  "  3. Deploy on Vercel and set DATABASE_URL (see README.md).",
  "",
  "Shortcut: open ankit-traders-source-bundle.html and click 'Download' next to a file,",
  "or 'Copy' to paste it into the GitHub editor.",
  "",
  `Files: ${entries.length}`,
  "",
].join("\n");

const parts = entries.map(([rel, content]) =>
  [
    bar,
    `BEGIN FILE: ${top}/${rel}`,
    bar,
    content,
    `END FILE: ${top}/${rel}`,
    "",
  ].join("\n"),
);

const txt = `${text}\n${parts.join("\n")}\n${bar}\nEND OF SOURCE (${entries.length} files)\n${bar}\n`;

/* ------------------------- self-extracting viewer ------------------------ */
const escapeHtml = (s) =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

const safeJson = json.replace(/</g, "\\u003c");

const viewer = `<!DOCTYPE html>
