  lines: MemoLine[];
  totalLabel: string;
  emptyText: string;
};

type PaperProps = {
  a5?: boolean;
  paperRef?: Ref<HTMLElement>;
  ariaLabel?: string;
};

function BrandRow({
  docType,
  numberTop,
  numberBottom,
}: {
  docType: string;
  numberTop: ReactNode;
  numberBottom: string;
}) {
  return (
    <div className="paper-brand-row">
      {/* eslint-disable-next-line @next/next/no-img-element */}
