  );
}

function PaperFooter() {
  return (
    <div className="paper-footer premium-footer">
      <span>Thank you! Visit again.</span>
      <span>Ankit Traders · Barkagoan Mansingh Patti</span>
    </div>
  );
}

function PaperShell({
  a5,
  paperRef,
  ariaLabel,
  docType,
  numberTop,
  numberBottom,
  children,
}: PaperProps & {
  docType: string;
  numberTop: ReactNode;
  numberBottom: string;
  children: ReactNode;
}) {
  return (
    <article
      ref={paperRef as Ref<HTMLElement>}
      className={`invoice-paper premium-paper${a5 ? " a5-paper" : ""}`}
