      <div className="paper-table-head collection-table-head">
        <span>DATE · DOCTOR NAME</span>
        <span>COLLECTION</span>
      </div>

      <Lines lines={memo.lines} emptyText={memo.emptyText} />

      <div className="paper-rule paper-rule-dashed" />
